1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
power: supply: pm8916_lbc: Fix use-after-free for extcon in
 IRQ handler

Using the `devm_` variant for requesting IRQ _before_ the `devm_`
variant for allocating/registering the `extcon` handle, means that the
`extcon` handle will be deallocated/unregistered _before_ the interrupt
handler (since `devm_` naturally deallocates in reverse allocation
order). This means that during removal, there is a race condition where
an interrupt can fire just _after_ the `extcon` handle has been
freed, *but* just _before_ the corresponding unregistration of the IRQ
handler has run.

This will lead to the IRQ handler calling `extcon_set_state_sync()` with
a freed `extcon` handle. Which usually crashes the system or otherwise
silently corrupts the memory...

Fix this racy use-after-free by making sure the IRQ is requested _after_
the registration of the `extcon` handle.

Fixes: f8d7a3d21160 ("power: supply: Add driver for pm8916 lbc")
Signed-off-by: Waqar Hameed <waqar.hameed@axis.com>
Reviewed-by: Nikita Travkin <nikita@trvn.ru>
Link: https://patch.msgid.link/e2a4cd2fcd42b6cd97d856c17c097289a2aed393.1769163273.git.waqar.hameed@axis.com
Signed-off-by: Sebastian Reichel <sebastian.reichel@collabora.com>

Here is the root cause:
The `devm_request_threaded_irq()` was called before `devm_extcon_dev_allocate()` and `devm_extcon_dev_register()`, causing the extcon device to be freed in reverse order during device removal while the IRQ handler might still be active, leading to a use-after-free when the handler calls `extcon_set_state_sync()` on the freed extcon handle.

Here is the patch:

 static int pm8916_lbc_charger_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct pm8916_lbc_charger *chg;
 	struct power_supply_config psy_cfg = {};
 	int ret, len, irq;
 	unsigned int tmp;

 	chg = devm_kzalloc(dev, sizeof(*chg), GFP_KERNEL);
 	if (!chg)
 		return -ENOMEM;

 	chg->dev = dev;

 	chg->regmap = dev_get_regmap(pdev->dev.parent, NULL);
 	if (!chg->regmap)
 		return -ENODEV;

 	len = device_property_count_u32(dev, "reg");
 	if (len < 0)
 		return len;
 	if (len != 4)
 		return dev_err_probe(dev, -EINVAL,
 				     "Wrong amount of reg values: %d (4 expected)\n", len);

 	ret = device_property_read_u32_array(dev, "reg", chg->reg, len);
 	if (ret)
 		return ret;

 	ret = regmap_bulk_read(chg->regmap, chg->reg[LBC_CHGR] + PM8916_PERPH_TYPE, &tmp, 2);
 	if (ret)
 		goto comm_error;
 	if (tmp != PM8916_LBC_CHGR_TYPE)
 		goto type_error;

 	ret = regmap_bulk_read(chg->regmap, chg->reg[LBC_BAT_IF] + PM8916_PERPH_TYPE, &tmp, 2);
 	if (ret)
 		goto comm_error;
 	if (tmp != PM8916_LBC_BAT_IF_TYPE)
 		goto type_error;

 	ret = regmap_bulk_read(chg->regmap, chg->reg[LBC_USB] + PM8916_PERPH_TYPE, &tmp, 2);
 	if (ret)
 		goto comm_error;
 	if (tmp != PM8916_LBC_USB_TYPE)
 		goto type_error;

 	ret = regmap_bulk_read(chg->regmap, chg->reg[LBC_MISC] + PM8916_PERPH_TYPE, &tmp, 2);
 	if (ret)
 		goto comm_error;
 	if (tmp != PM8916_LBC_MISC_TYPE)
 		goto type_error;

 	ret = regmap_read(chg->regmap, chg->reg[LBC_CHGR] + PM8916_LBC_CHGR_CHG_OPTION, &tmp);
 	if (ret)
 		goto comm_error;
 	if (tmp != PM8916_LBC_CHGR_PMIC_CHARGER)
 		dev_err_probe(dev, -ENODEV, "The system is using an external charger\n");

 	ret = pm8916_lbc_charger_probe_dt(chg);
 	if (ret)
 		dev_err_probe(dev, ret, "Error while parsing device tree\n");

 	psy_cfg.drv_data = chg;
 	psy_cfg.fwnode = dev_fwnode(dev);

 	chg->charger = devm_power_supply_register(dev, &pm8916_lbc_charger_psy_desc, &psy_cfg);
 	if (IS_ERR(chg->charger))
 		return dev_err_probe(dev, PTR_ERR(chg->charger), "Unable to register charger\n");

 	ret = power_supply_get_battery_info(chg->charger, &chg->info);
 	if (ret)
 		return dev_err_probe(dev, ret, "Unable to get battery info\n");

 	irq = platform_get_irq_byname(pdev, "usb_vbus");
 	if (irq < 0)
 		return irq;

-	ret = devm_request_threaded_irq(dev, irq, NULL, pm8916_lbc_charger_state_changed_irq,
-					IRQF_ONESHOT, "pm8916_lbc", chg);
-	if (ret)
-		return ret;
-
 	chg->edev = devm_extcon_dev_allocate(dev, pm8916_lbc_charger_cable);
 	if (IS_ERR(chg->edev))
 		return PTR_ERR(chg->edev);

 	ret = devm_extcon_dev_register(dev, chg->edev);
 	if (ret < 0)
 		return dev_err_probe(dev, ret, "failed to register extcon device\n");

+	ret = devm_request_threaded_irq(dev, irq, NULL, pm8916_lbc_charger_state_changed_irq,
+					IRQF_ONESHOT, "pm8916_lbc", chg);
+	if (ret)
+		return ret;
+
 	ret = regmap_read(chg->regmap, chg->reg[LBC_USB] + PM8916_INT_RT_STS, &tmp);
 	if (ret)
 		goto comm_error;

 	chg->online = !!(tmp & PM8916_LBC_USB_USBIN_VALID);
 	extcon_set_state_sync(chg->edev, EXTCON_USB, chg->online);

 	chg->charge_voltage_max = chg->info->voltage_max_design_uv;
 	ret = pm8916_lbc_charger_configure(chg);
 	if (ret)
 		return ret;

 	return 0;

 comm_error:
 	return dev_err_probe(dev, ret, "Unable to communicate with device\n");

 type_error:
 	return dev_err_probe(dev, -ENODEV, "Device reported wrong type: 0x%X\n", tmp);
 }



